(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kinds=['Lo observo en la imagen','Lo informa la fuente','Es una interpretación','No está justificado'];
let cases=[],active='alimentos',position=0,answered=false,score=0,notes={},depth='explorar';
const current=()=>cases.find(c=>c.id===active),note=()=>notes[active]||(notes[active]={observe:'',ask:'',explain:''});
function render(){const c=current();if(!c)return;const n=note();$('#dailyLifeApp').innerHTML=`<div class="dl-controls"><label>Caso<select id="dlCase">${cases.map(x=>`<option value="${x.id}" ${active===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label>Profundidad<select id="dlDepth">${[['explorar','Explorar'],['comprender','Comprender'],['profundizar','Profundizar']].map(([id,l])=>`<option value="${id}" ${depth===id?'selected':''}>${l}</option>`).join('')}</select></label><button id="dlProject" class="atlas-outline">Proyectar</button></div><header class="dl-heading"><p class="eyebrow">${esc(c.period)}</p><h2>${esc(c.question)}</h2><p>${esc(c.context)}</p></header><div class="dl-sources">${c.sources.map((s,i)=>`<article class="dl-source"><p class="eyebrow">FUENTE ${i+1} · ${esc(s.kind)}</p><h3>${esc(s.title)}</h3>${s.image?`<figure><div class="dl-image" id="dlImage${i}" tabindex="0" aria-label="Imagen ampliable; usa el control y desplázate para observar detalles"><img src="${s.image}" alt="${esc(s.title)}" loading="lazy"></div><label class="dl-zoom">Ampliación <input type="range" data-dl-zoom="${i}" min="1" max="3" step=".25" value="1"><output id="dlZoom${i}">1×</output></label><figcaption>${esc(s.credit)}</figcaption></figure>`:'<div class="dl-document"><span>DOCUMENTO / CONTEXTO</span><p>Síntesis educativa; no es una transcripción ni una imagen del original.</p></div>'}<dl><dt>Fecha</dt><dd>${esc(s.date)}</dd><dt>Procedencia</dt><dd>${esc(s.origin)}</dd></dl><p>${esc(s.text)}</p><details><summary>Qué no permite concluir</summary><p>${esc(s.limits)}</p></details><a class="atlas-outline" href="${s.url}" target="_blank" rel="noopener">Consultar el original y su ficha</a></article>`).join('')}</div><div class="dl-learning"><section class="dl-challenge"><p class="eyebrow">DETECTIVE DE EVIDENCIAS</p>${challenge(c)}</section><section class="dl-notes"><h2>Mi investigación</h2><p>${depth==='explorar'?'Di, escribe o dibuja un detalle. Explica dónde lo encontraste.':depth==='comprender'?'Compara las dos fuentes: una semejanza, una diferencia y un límite.':'Distingue autoría, fecha, contexto y propósito. ¿Son fuentes independientes? ¿Qué voces faltan?'} </p>${[['observe','1. Observo o encuentro'],['ask','2. Me pregunto'],['explain','3. Concluyo con evidencia']].map(([id,l])=>`<label for="dlNote-${id}">${l}</label><textarea id="dlNote-${id}" data-dl-note="${id}" rows="3">${esc(n[id])}</textarea>`).join('')}<p class="dl-note-status">Notas temporales: permanecen al cambiar de caso mientras esta página esté abierta.</p><a class="atlas-outline" href="#aventura-grano">Investigar: Del grano a las ciudades</a><button id="dlPrint" class="atlas-button">Imprimir mi investigación</button><a class="atlas-outline" href="${c.route}">Conectar con la ruta histórica</a><details><summary>Dinámica en pareja · 20 minutos</summary><ol><li>4 min: cada persona observa sin leer la ficha.</li><li>5 min: comparen con lo que informa el catálogo.</li><li>6 min: clasifiquen afirmaciones y justifiquen.</li><li>5 min: revisen una conclusión y formulen una pregunta nueva.</li></ol><p>Una persona propone y otra pide evidencia. Después intercambien papeles. Se admiten respuestas orales, escritas o dibujadas.</p></details></section></div>`;bind();}
function challenge(c){if(position>=c.claims.length)return `<h3>${score} de ${c.claims.length} clasificaciones acertadas</h3><p>Elige una afirmación que revisaste y explica por qué cambiaste de idea.</p><button id="dlReplay" class="atlas-button">Repetir el reto</button>`;return `<p>Afirmación ${position+1} de ${c.claims.length}</p><blockquote>${esc(c.claims[position][0])}</blockquote><div class="dl-answers">${kinds.map((k,i)=>`<button data-dl-answer="${i}" ${answered?'disabled':''} class="${answered&&i===c.claims[position][1]?'dl-correct':''}">${k}</button>`).join('')}</div><div id="dlFeedback" role="status">${answered?`<p>${esc(c.claims[position][2])}</p><p>Clasificación: ${esc(kinds[c.claims[position][1]])}.</p>`:''}</div><button id="dlNext" class="atlas-button" ${answered?'':'disabled'}>Siguiente afirmación</button>`;}
function bind(){
 $('#dlCase').onchange=e=>{active=e.target.value;position=0;score=0;answered=false;render();};$('#dlDepth').onchange=e=>{depth=e.target.value;render();};$('#dlProject').onclick=()=>$('#projectorBtn').click();$('#dlPrint').onclick=()=>window.print();
 $$('[data-dl-note]').forEach(el=>el.oninput=()=>note()[el.dataset.dlNote]=el.value);
 $$('[data-dl-zoom]').forEach(el=>el.oninput=()=>{const i=el.dataset.dlZoom;const img=$('#dlImage'+i+' img');img.style.width=(Number(el.value)*100)+'%';img.style.maxWidth='none';$('#dlZoom'+i).textContent=el.value+'×';});
 $$('[data-dl-answer]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const claim=current().claims[position],ok=+b.dataset.dlAnswer===claim[1];if(ok)score++;$$('[data-dl-answer]').forEach(x=>{x.disabled=true;x.classList.toggle('dl-correct',+x.dataset.dlAnswer===claim[1]);});$('#dlFeedback').innerHTML=`<strong>${ok?'Clasificación justificada.':'Revisemos de dónde viene la afirmación.'}</strong><p>${esc(claim[2])}</p><p>Clasificación: ${esc(kinds[claim[1]])}.</p>`;$('#dlNext').disabled=false;});
 if($('#dlNext'))$('#dlNext').onclick=()=>{if(!answered)return;position++;answered=false;render();};if($('#dlReplay'))$('#dlReplay').onclick=()=>{position=0;score=0;answered=false;render();};
}
async function init(){try{const r=await fetch('data/daily-life.json');if(!r.ok)throw Error('cases');cases=(await r.json()).cases;depth=localStorage.getItem('atlas-audience')||'explorar';if(!['explorar','comprender','profundizar'].includes(depth))depth='explorar';render();}catch(e){$('#dailyLifeApp').innerHTML='<p>No se pudieron cargar los casos.</p><button id="dlRetry" class="atlas-button">Reintentar</button>';$('#dlRetry').onclick=init;}}
window.AtlasDailyLife={init};init();
})();
